+	}
+}
+
+func (a *app) runGenericLeaf(args []string, help string) int {
+	if hasHelp(args) {
+		io.WriteString(a.stdout, help)
+		return 0
+	}
+	return a.fail(errors.New("not implemented"))
+}
+
+func (a *app) runSchemaFmt(args []string) int {
