+func parseFlags(args []string, defs []flagDef) (parsedFlags, error) {
+	byLong := map[string]flagDef{}
+	byShort := map[string]flagDef{}
+	for _, def := range defs {
+		byLong[def.Name] = def
+		if def.Short != "" {
+			byShort[def.Short] = def
+		}
+	}
+	parsed := parsedFlags{
+		values: map[string][]string{},
+		set:    map[string]bool{},
+	}
+	for i := 0; i < len(args); i++ {
+		arg := args[i]
+		if arg == "--" {
+			parsed.Args = append(parsed.Args, args[i+1:]...)
+			break
+		}
+		if strings.HasPrefix(arg, "--") && len(arg) > 2 {
+			name, value, hasValue := splitFlag(arg[2:])
+			def, ok := byLong[name]
+			if !ok {
+				return parsed, fmt.Errorf("unknown flag: --%s", name)
