+			resolved, next, err := consumeFlagValue(def, value, hasValue, args, i)
+			if err != nil {
+				return parsed, err
+			}
+			i = next
+			recordFlag(parsed, def, resolved)
+			continue
+		}
+		if strings.HasPrefix(arg, "-") && arg != "-" {
+			name, value, hasValue := splitFlag(arg[1:])
+			def, ok := byShort[name]
+			if !ok {
+				return parsed, fmt.Errorf("unknown shorthand flag: '%s' in -%s", name, name)
+			}
+			resolved, next, err := consumeFlagValue(def, value, hasValue, args, i)
+			if err != nil {
+				return parsed, err
+			}
+			i = next
+			recordFlag(parsed, def, resolved)
+			continue
+		}
+		parsed.Args = append(parsed.Args, arg)
+	}
+	return parsed, nil
