+		return inline, index, nil
+	}
+	if index+1 >= len(args) {
+		return "", index, fmt.Errorf("flag needs an argument: --%s", def.Name)
+	}
+	value := args[index+1]
+	if def.Kind == flagVars && !strings.Contains(value, "=") {
+		return "", index, fmt.Errorf("invalid argument %q for %q flag: variables must be format as key=value, got: %q", value, "--"+def.Name, value)
+	}
+	return value, index + 1, nil
