package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type app struct {
	stdout io.Writer
	stderr io.Writer
}

func newApp(stdout, stderr io.Writer) *app {
	return &app{stdout: stdout, stderr: stderr}
}

func (a *app) Run(args []string) int {
	if len(args) == 0 {
		io.WriteString(a.stdout, rootHelp)
		return 0
	}
	if isHelpArg(args[0]) {
		io.WriteString(a.stdout, rootHelp)
		return 0
	}
	switch args[0] {
	case "help":
		return a.runHelp(args[1:])
	case "version":
		return a.runVersion(args[1:])
	case "license":
		return a.runLicense(args[1:])
	case "completion":
		return a.runCompletion(args[1:])
	case "schema":
		return a.runSchema(args[1:])
	case "migrate":
		return a.runMigrate(args[1:])
	case "__complete":
		return a.runComplete(args[1:], false)
	case "__completeNoDesc":
		return a.runComplete(args[1:], true)
	default:
		return a.unknownCommand(args[0], "atlas")
	}
}

func (a *app) runHelp(args []string) int {
	if len(args) == 0 {
		io.WriteString(a.stdout, rootHelp)
		return 0
	}
	if help := helpFor(args); help != "" {
		io.WriteString(a.stdout, help)
		return 0
	}
	fmt.Fprintf(a.stdout, "Unknown help topic [`%s`]\n", strings.Join(args, " "))
	io.WriteString(a.stdout, rootHelpNoFlags())
	return 0
}

func (a *app) runVersion(args []string) int {
	if hasHelp(args) {
		io.WriteString(a.stdout, versionHelp)
		return 0
	}
	io.WriteString(a.stdout, versionOutput)
	return 0
}

func (a *app) runLicense(args []string) int {
	if hasHelp(args) {
		io.WriteString(a.stdout, licenseHelp)
		return 0
	}
	io.WriteString(a.stdout, licenseOutput)
	return 0
}

func (a *app) runCompletion(args []string) int {
	if len(args) == 0 || hasHelp(args) {
		io.WriteString(a.stdout, completionHelp)
		return 0
	}
	switch args[0] {
	case "bash":
		return a.runCompletionShell(args[1:], "bash")
	case "fish":
		return a.runCompletionShell(args[1:], "fish")
	case "powershell":
		return a.runCompletionShell(args[1:], "powershell")
	case "zsh":
		return a.runCompletionShell(args[1:], "zsh")
	default:
		return a.unknownCommand(args[0], "atlas completion")
	}
}

func (a *app) runSchema(args []string) int {
	if len(args) == 0 || hasHelp(args[:min(1, len(args))]) {
		io.WriteString(a.stdout, schemaHelp)
		return 0
	}
	if args[0] == "help" {
		return a.runHelp(append([]string{"schema"}, args[1:]...))
	}
	switch args[0] {
	case "fmt":
		return a.runSchemaFmt(args[1:])
	case "inspect":
		return a.runSchemaInspect(args[1:])
	case "apply":
		return a.runGenericLeaf(args[1:], schemaApplyHelp)
	case "diff":
		return a.runGenericLeaf(args[1:], schemaDiffHelp)
	case "clean":
		return a.runGenericLeaf(args[1:], schemaCleanHelp)
	default:
		return a.unknownCommand(args[0], "atlas schema")
	}
}

func (a *app) runMigrate(args []string) int {
	if len(args) == 0 || hasHelp(args[:min(1, len(args))]) {
		io.WriteString(a.stdout, migrateHelp)
		return 0
	}
	if args[0] == "help" {
		return a.runHelp(append([]string{"migrate"}, args[1:]...))
	}
	switch args[0] {
	case "hash":
		return a.runMigrateHash(args[1:])
	case "new":
		return a.runMigrateNew(args[1:])
	case "validate":
		return a.runMigrateValidate(args[1:])
	case "apply":
		return a.runGenericLeaf(args[1:], migrateApplyHelp)
	case "diff":
		return a.runGenericLeaf(args[1:], migrateDiffHelp)
	case "import":
		return a.runGenericLeaf(args[1:], migrateImportHelp)
	case "lint":
		return a.runGenericLeaf(args[1:], migrateLintHelp)
	case "set":
		return a.runGenericLeaf(args[1:], migrateSetHelp)
	case "status":
		return a.runGenericLeaf(args[1:], migrateStatusHelp)
	default:
		return a.unknownCommand(args[0], "atlas migrate")
	}
}

func (a *app) runGenericLeaf(args []string, help string) int {
	if hasHelp(args) {
		io.WriteString(a.stdout, help)
		return 0
	}
	return a.fail(errors.New("not implemented"))
}

func (a *app) runSchemaFmt(args []string) int {
	parsed, err := parseFlags(args, schemaFmtFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		io.WriteString(a.stdout, schemaFmtHelp)
		return 0
	}
	paths := parsed.Args
	if len(paths) == 0 {
		paths = []string{"."}
	}
	changed, err := formatPaths(paths)
	if err != nil {
		return a.fail(err)
	}
	for _, path := range changed {
		fmt.Fprintln(a.stdout, path)
	}
	return 0
}

func (a *app) runSchemaInspect(args []string) int {
	parsed, err := parseFlags(args, schemaInspectFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		io.WriteString(a.stdout, schemaInspectHelp)
		return 0
	}
	cfg, err := maybeLoadCommandConfig(parsed, true)
	if err != nil {
		return a.fail(err)
	}
	url := parsed.String("url")
	if url == "" && cfg != nil && parsed.String("env") != "" {
		url = cfg.EnvValue("url")
	}
	if url == "" {
		return a.fail(errors.New(`required flag(s) "url" not set`))
	}
	state, err := inspectURL(url)
	if err != nil {
		return a.fail(err)
	}
	if format := parsed.String("format"); format != "" {
		out, err := renderInspectTemplate(format, state)
		if err != nil {
			return a.fail(err)
		}
		io.WriteString(a.stdout, out)
		return 0
	}
	io.WriteString(a.stdout, renderHCL(state))
	return 0
}

func (a *app) runMigrateHash(args []string) int {
	parsed, err := parseFlags(args, migrateDirFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		io.WriteString(a.stdout, migrateHashHelp)
		return 0
	}
	cfg, err := maybeLoadCommandConfig(parsed, false)
	if err != nil {
		return a.fail(err)
	}
	dirURL := parsed.StringDefault("dir", "file://migrations")
	if dirURL == "" && cfg != nil && parsed.String("env") != "" {
		dirURL = cfg.EnvValue("dir")
	}
	if dirURL == "" {
		dirURL = "file://migrations"
	}
	dir, err := filePathFromURL(dirURL)
	if err != nil {
		return a.fail(err)
	}
	if err := writeMigrationSum(dir); err != nil {
		return a.fail(err)
	}
	return 0
}

func (a *app) runMigrateNew(args []string) int {
	parsed, err := parseFlags(args, migrateNewFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		io.WriteString(a.stdout, migrateNewHelp)
		return 0
	}
	if len(parsed.Args) > 1 {
		return a.fail(fmt.Errorf("accepts at most 1 arg(s), received %d", len(parsed.Args)))
	}
	cfg, err := maybeLoadCommandConfig(parsed, false)
	if err != nil {
		return a.fail(err)
	}
	dirURL := parsed.StringDefault("dir", "file://migrations")
	if dirURL == "" && cfg != nil && parsed.String("env") != "" {
		dirURL = cfg.EnvValue("dir")
	}
	if dirURL == "" {
		dirURL = "file://migrations"
	}
	dir, err := filePathFromURL(dirURL)
	if err != nil {
		return a.fail(err)
	}
	name := ""
	if len(parsed.Args) == 1 {
		name = parsed.Args[0]
	}
	if err := createMigration(dir, time.Now().UTC(), name); err != nil {
		return a.fail(err)
	}
	return 0
}

func (a *app) runMigrateValidate(args []string) int {
	parsed, err := parseFlags(args, migrateValidateFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		io.WriteString(a.stdout, migrateValidateHelp)
		return 0
	}
	cfg, err := maybeLoadCommandConfig(parsed, false)
	if err != nil {
		return a.fail(err)
	}
	dirURL := parsed.StringDefault("dir", "file://migrations")
	if dirURL == "" && cfg != nil && parsed.String("env") != "" {
		dirURL = cfg.EnvValue("dir")
	}
	if dirURL == "" {
		dirURL = "file://migrations"
	}
	dir, err := filePathFromURL(dirURL)
	if err != nil {
		return a.fail(err)
	}
	if err := validateMigrationDir(dir); err != nil {
		return a.fail(err)
	}
	return 0
}

func (a *app) runCompletionShell(args []string, shell string) int {
	parsed, err := parseFlags(args, completionShellFlagDefs)
	if err != nil {
		return a.fail(err)
	}
	if parsed.Bool("help") {
		switch shell {
		case "bash":
			io.WriteString(a.stdout, completionBashHelp)
		case "fish":
			io.WriteString(a.stdout, completionFishHelp)
		case "powershell":
			io.WriteString(a.stdout, completionPowershellHelp)
		case "zsh":
			io.WriteString(a.stdout, completionZshHelp)
		}
		return 0
	}
	noDesc := parsed.Bool("no-descriptions")
	switch shell {
	case "bash":
		io.WriteString(a.stdout, bashCompletionScript(noDesc))
	case "fish":
		io.WriteString(a.stdout, fishCompletionScript(noDesc))
	case "powershell":
		io.WriteString(a.stdout, powershellCompletionScript(noDesc))
	case "zsh":
		io.WriteString(a.stdout, zshCompletionScript(noDesc))
	}
	return 0
}

func (a *app) runComplete(args []string, noDesc bool) int {
	suggestions := completionSuggestions(args, noDesc)
	for _, item := range suggestions {
		fmt.Fprintln(a.stdout, item)
	}
	fmt.Fprintln(a.stdout, ":4")
	return 0
}

func (a *app) unknownCommand(name, parent string) int {
	fmt.Fprintf(a.stderr, "Error: unknown command %q for %q\n", name, parentName(parent))
	fmt.Fprintf(a.stderr, "Run '%s --help' for usage.\n", parent)
	return 1
}

func (a *app) fail(err error) int {
	fmt.Fprintf(a.stderr, "Error: %v\n", err)
	return 1
}

func maybeLoadCommandConfig(parsed parsedFlags, envOptional bool) (*EvalConfig, error) {
	load := parsed.Set("config") || parsed.String("env") != ""
	if !load {
		return nil, nil
	}
	configURL := parsed.StringDefault("config", "file://atlas.hcl")
	configPath, err := filePathFromURL(configURL)
	if err != nil {
		return nil, err
	}
	cfg, err := LoadEvalConfig(configPath)
	if err != nil {
		return nil, err
	}
	envName := parsed.String("env")
	if envName != "" {
		if err := cfg.UseEnv(envName); err != nil {
			return nil, err
		}
	}
	for _, assign := range parsed.Strings("var") {
		parts := strings.SplitN(assign, "=", 2)
		cfg.SetVar(parts[0], parts[1])
	}
	if envName != "" {
		if err := cfg.Evaluate(); err != nil {
			return nil, err
		}
	}
	if parsed.Set("config") && envName == "" {
		if err := cfg.ParseOnly(); err != nil {
			return nil, err
		}
	}
	if !envOptional && parsed.String("env") == "" && parsed.Set("config") {
		if err := cfg.ParseOnly(); err != nil {
			return nil, err
		}
	}
	return cfg, nil
}

func rootHelpNoFlags() string {
	return `Usage:
  atlas [command]

Available Commands:
  completion  Generate the autocompletion script for the specified shell
  help        Help about any command
  license     Display license information
  migrate     Manage versioned migration files
  schema      Work with atlas schemas.
  version     Prints this Atlas CLI version information.

Use "atlas [command] --help" for more information about a command.
`
}

func isHelpArg(s string) bool {
	return s == "-h" || s == "--help"
}

func hasHelp(args []string) bool {
	for _, arg := range args {
		if isHelpArg(arg) {
			return true
		}
	}
	return false
}

func parentName(parent string) string {
	parts := strings.Fields(parent)
	if len(parts) == 0 {
		return parent
	}
	return parts[len(parts)-1]
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

type flagKind int

const (
	flagBool flagKind = iota
	flagString
	flagStrings
	flagVars
)

type flagDef struct {
	Name  string
	Short string
	Kind  flagKind
}

type parsedFlags struct {
	values map[string][]string
	set    map[string]bool
	Args   []string
}

func (p parsedFlags) String(name string) string {
	values := p.values[name]
	if len(values) == 0 {
		return ""
	}
	return values[len(values)-1]
}

func (p parsedFlags) StringDefault(name, fallback string) string {
	if p.Set(name) {
		return p.String(name)
	}
	return fallback
}

func (p parsedFlags) Strings(name string) []string {
	return append([]string(nil), p.values[name]...)
}

func (p parsedFlags) Bool(name string) bool {
	return p.Set(name)
}

func (p parsedFlags) Set(name string) bool {
	return p.set[name]
}

func parseFlags(args []string, defs []flagDef) (parsedFlags, error) {
	byLong := map[string]flagDef{}
	byShort := map[string]flagDef{}
	for _, def := range defs {
		byLong[def.Name] = def
		if def.Short != "" {
			byShort[def.Short] = def
		}
	}
	parsed := parsedFlags{
		values: map[string][]string{},
		set:    map[string]bool{},
	}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			parsed.Args = append(parsed.Args, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") && len(arg) > 2 {
			name, value, hasValue := splitFlag(arg[2:])
			def, ok := byLong[name]
			if !ok {
				return parsed, fmt.Errorf("unknown flag: --%s", name)
			}
			resolved, next, err := consumeFlagValue(def, value, hasValue, args, i)
			if err != nil {
				return parsed, err
			}
			i = next
			recordFlag(parsed, def, resolved)
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			name, value, hasValue := splitFlag(arg[1:])
			def, ok := byShort[name]
			if !ok {
				return parsed, fmt.Errorf("unknown shorthand flag: '%s' in -%s", name, name)
			}
			resolved, next, err := consumeFlagValue(def, value, hasValue, args, i)
			if err != nil {
				return parsed, err
			}
			i = next
			recordFlag(parsed, def, resolved)
			continue
		}
		parsed.Args = append(parsed.Args, arg)
	}
	return parsed, nil
}

func splitFlag(arg string) (name, value string, hasValue bool) {
	if idx := strings.IndexByte(arg, '='); idx >= 0 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func consumeFlagValue(def flagDef, inline string, hasInline bool, args []string, index int) (string, int, error) {
	if def.Kind == flagBool {
		return "", index, nil
	}
	if hasInline {
		if def.Kind == flagVars && !strings.Contains(inline, "=") {
			return "", index, fmt.Errorf("invalid argument %q for %q flag: variables must be format as key=value, got: %q", inline, "--"+def.Name, inline)
		}
		return inline, index, nil
	}
	if index+1 >= len(args) {
		return "", index, fmt.Errorf("flag needs an argument: --%s", def.Name)
	}
	value := args[index+1]
	if def.Kind == flagVars && !strings.Contains(value, "=") {
		return "", index, fmt.Errorf("invalid argument %q for %q flag: variables must be format as key=value, got: %q", value, "--"+def.Name, value)
	}
	return value, index + 1, nil
}

func recordFlag(parsed parsedFlags, def flagDef, value string) {
	parsed.set[def.Name] = true
	switch def.Kind {
	case flagBool:
		return
	default:
		parsed.values[def.Name] = append(parsed.values[def.Name], value)
	}
}

var (
	globalFlagDefs = []flagDef{
		{Name: "config", Short: "c", Kind: flagString},
		{Name: "env", Kind: flagString},
		{Name: "var", Kind: flagVars},
		{Name: "help", Short: "h", Kind: flagBool},
	}

	schemaFmtFlagDefs = globalFlagDefs

	schemaInspectFlagDefs = appendDefs(globalFlagDefs,
		flagDef{Name: "url", Short: "u", Kind: flagString},
		flagDef{Name: "dev-url", Kind: flagString},
		flagDef{Name: "schema", Short: "s", Kind: flagStrings},
		flagDef{Name: "exclude", Kind: flagStrings},
		flagDef{Name: "format", Kind: flagString},
	)

	migrateDirFlagDefs = appendDefs(globalFlagDefs,
		flagDef{Name: "dir", Kind: flagString},
		flagDef{Name: "dir-format", Kind: flagString},
	)

	migrateNewFlagDefs = appendDefs(migrateDirFlagDefs,
		flagDef{Name: "edit", Kind: flagBool},
	)

	migrateValidateFlagDefs = appendDefs(migrateDirFlagDefs,
		flagDef{Name: "dev-url", Kind: flagString},
	)

	completionShellFlagDefs = []flagDef{
		{Name: "help", Short: "h", Kind: flagBool},
		{Name: "no-descriptions", Kind: flagBool},
	}
