func appendDefs(base []flagDef, defs ...flagDef) []flagDef {
	out := make([]flagDef, 0, len(base)+len(defs))
	out = append(out, base...)
	out = append(out, defs...)
	return out
}

func formatPaths(paths []string) ([]string, error) {
	var files []string
	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			return nil, err
		}
		if info.IsDir() {
			collected, err := collectHCLFiles(path)
			if err != nil {
				return nil, err
			}
			files = append(files, collected...)
			continue
		}
		if filepath.Ext(path) == ".hcl" {
			files = append(files, path)
		}
	}
	sort.Strings(files)
	var changed []string
	for _, path := range files {
		src, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		formatted := FormatHCL(src)
		if string(formatted) == string(src) {
			continue
		}
		if err := os.WriteFile(path, formatted, 0o644); err != nil {
			return nil, err
		}
		changed = append(changed, path)
	}
	return changed, nil
}

func collectHCLFiles(root string) ([]string, error) {
	var files []string
	entries, err := os.ReadDir(root)
	if err != nil {
		return nil, err
	}
	for _, entry := range entries {
		path := filepath.Join(root, entry.Name())
		if entry.IsDir() {
			nested, err := collectHCLFiles(path)
			if err != nil {
				return nil, err
			}
			files = append(files, nested...)
			continue
		}
		if filepath.Ext(entry.Name()) == ".hcl" {
			files = append(files, path)
		}
	}
	return files, nil
}

