package main

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenKind int

const (
	tokenEOF tokenKind = iota
	tokenIdent
	tokenString
	tokenNumber
	tokenLBrace
	tokenRBrace
	tokenLBracket
	tokenRBracket
	tokenLParen
	tokenRParen
	tokenEqual
	tokenComma
	tokenDot
)

type token struct {
	Kind tokenKind
	Text string
	Line int
	Col  int
}

type parseError struct {
	Path  string
	Token token
}

func (e parseError) Error() string {
	end := e.Token.Col + utf8.RuneCountInString(e.Token.Text)
	return fmt.Sprintf("%s:%d,%d-%d: Argument or block definition required; An argument or block definition is required here.", e.Path, e.Token.Line, e.Token.Col, end)
}

type fileNode struct {
	Items []node
}

type node interface {
	isNode()
}

type blockNode struct {
	Type   string
	Labels []label
	Items  []node
}

type attrNode struct {
	Name string
	Expr expr
}

func (*blockNode) isNode() {}
func (*attrNode) isNode()  {}

type label struct {
	Raw    string
	Value  string
	Quoted bool
}

type expr interface {
	isExpr()
}

type (
	stringExpr struct {
		Raw string
	}
	numberExpr struct {
		Raw string
	}
	boolExpr struct {
		Value bool
	}
	identExpr struct {
		Name string
	}
	traversalExpr struct {
		Parts []string
	}
	callExpr struct {
		Name string
		Args []expr
	}
	listExpr struct {
		Elems []expr
	}
)

func (*stringExpr) isExpr()    {}
func (*numberExpr) isExpr()    {}
func (*boolExpr) isExpr()      {}
func (*identExpr) isExpr()     {}
func (*traversalExpr) isExpr() {}
func (*callExpr) isExpr()      {}
func (*listExpr) isExpr()      {}

type parser struct {
	tokens []token
	pos    int
	path   string
}

func tokenize(src []byte) []token {
	var tokens []token
	line, col := 1, 1
	for i := 0; i < len(src); {
		r, size := utf8.DecodeRune(src[i:])
		switch {
		case r == '\n':
			line++
			col = 1
			i += size
		case r == '\r':
			i += size
		case r == ' ' || r == '\t':
			col += size
			i += size
		case r == '#':
			for i < len(src) {
				r, size = utf8.DecodeRune(src[i:])
				i += size
				if r == '\n' {
					line++
					col = 1
					break
				}
			}
		case r == '/' && i+1 < len(src) && src[i+1] == '/':
			i += 2
			col += 2
			for i < len(src) {
				r, size = utf8.DecodeRune(src[i:])
				i += size
				if r == '\n' {
					line++
					col = 1
					break
				}
			}
		case r == '/' && i+1 < len(src) && src[i+1] == '*':
			i += 2
			col += 2
			for i < len(src)-1 {
				r, size = utf8.DecodeRune(src[i:])
				if r == '\n' {
					line++
					col = 1
					i += size
					continue
				}
				if src[i] == '*' && src[i+1] == '/' {
					i += 2
					col += 2
					break
				}
				i += size
				col += size
			}
		case r == '"':
			startCol := col
			start := i
			i += size
			col += size
			for i < len(src) {
				r, size = utf8.DecodeRune(src[i:])
				i += size
				col += size
				if r == '\\' && i < len(src) {
					_, escSize := utf8.DecodeRune(src[i:])
					i += escSize
					col += escSize
					continue
				}
				if r == '"' {
					break
				}
				if r == '\n' {
					line++
					col = 1
				}
			}
			tokens = append(tokens, token{Kind: tokenString, Text: string(src[start:i]), Line: line, Col: startCol})
		case isIdentStart(r):
			startCol := col
			start := i
			i += size
			col += size
			for i < len(src) {
				r, size = utf8.DecodeRune(src[i:])
				if !isIdentPart(r) {
					break
				}
				i += size
				col += size
			}
			tokens = append(tokens, token{Kind: tokenIdent, Text: string(src[start:i]), Line: line, Col: startCol})
		case unicode.IsDigit(r):
			startCol := col
			start := i
			i += size
			col += size
			for i < len(src) {
				r, size = utf8.DecodeRune(src[i:])
				if !unicode.IsDigit(r) {
					break
				}
				i += size
				col += size
			}
			tokens = append(tokens, token{Kind: tokenNumber, Text: string(src[start:i]), Line: line, Col: startCol})
		default:
			kind := tokenEOF
			switch r {
			case '{':
				kind = tokenLBrace
			case '}':
				kind = tokenRBrace
			case '[':
				kind = tokenLBracket
			case ']':
				kind = tokenRBracket
			case '(':
				kind = tokenLParen
			case ')':
				kind = tokenRParen
			case '=':
				kind = tokenEqual
			case ',':
				kind = tokenComma
			case '.':
				kind = tokenDot
			}
			if kind != tokenEOF {
				tokens = append(tokens, token{Kind: kind, Text: string(r), Line: line, Col: col})
			}
			i += size
			col += size
		}
	}
	tokens = append(tokens, token{Kind: tokenEOF, Line: line, Col: col})
	return tokens
}

func isIdentStart(r rune) bool {
	return unicode.IsLetter(r) || r == '_'
}

func isIdentPart(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '-'
}

func parseFile(path string, src []byte) (*fileNode, error) {
	p := parser{tokens: tokenize(src), path: path}
	return p.parseFile()
}

func (p *parser) parseFile() (*fileNode, error) {
	items, err := p.parseItems(tokenEOF)
	if err != nil {
		return nil, err
	}
	if p.peek().Kind != tokenEOF {
		return nil, parseError{Path: p.path, Token: p.peek()}
	}
	return &fileNode{Items: items}, nil
}

func (p *parser) parseItems(until tokenKind) ([]node, error) {
	var items []node
	for {
		tok := p.peek()
		if tok.Kind == until || tok.Kind == tokenEOF {
			break
		}
		if tok.Kind != tokenIdent {
			return nil, parseError{Path: p.path, Token: tok}
		}
		item, err := p.parseItem()
		if err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	return items, nil
}

func (p *parser) parseItem() (node, error) {
	name := p.next()
	if p.peek().Kind == tokenEqual {
		p.next()
		value, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		return &attrNode{Name: name.Text, Expr: value}, nil
	}
	var labels []label
	for {
		switch p.peek().Kind {
		case tokenString:
			raw := p.next().Text
			value, _ := strconv.Unquote(raw)
			labels = append(labels, label{Raw: raw, Value: value, Quoted: true})
		case tokenIdent:
			raw := p.next().Text
			labels = append(labels, label{Raw: raw, Value: raw})
		default:
			goto done
		}
	}
done:
	if p.peek().Kind != tokenLBrace {
		return nil, parseError{Path: p.path, Token: p.peek()}
	}
	p.next()
	items, err := p.parseItems(tokenRBrace)
	if err != nil {
		return nil, err
	}
	if p.peek().Kind != tokenRBrace {
		return nil, parseError{Path: p.path, Token: p.peek()}
	}
	p.next()
	return &blockNode{Type: name.Text, Labels: labels, Items: items}, nil
}

func (p *parser) parseExpr() (expr, error) {
	switch tok := p.peek(); tok.Kind {
	case tokenString:
		p.next()
		return &stringExpr{Raw: tok.Text}, nil
	case tokenNumber:
		p.next()
		return &numberExpr{Raw: tok.Text}, nil
	case tokenIdent:
		p.next()
		name := tok.Text
		if p.peek().Kind == tokenLParen {
			p.next()
			var args []expr
			if p.peek().Kind != tokenRParen {
				for {
					arg, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					args = append(args, arg)
					if p.peek().Kind != tokenComma {
						break
					}
					p.next()
				}
			}
			if p.peek().Kind != tokenRParen {
				return nil, parseError{Path: p.path, Token: p.peek()}
			}
			p.next()
			return &callExpr{Name: name, Args: args}, nil
		}
		if name == "true" {
			return &boolExpr{Value: true}, nil
		}
		if name == "false" {
			return &boolExpr{Value: false}, nil
		}
		parts := []string{name}
		for p.peek().Kind == tokenDot {
			p.next()
			if p.peek().Kind != tokenIdent {
				return nil, parseError{Path: p.path, Token: p.peek()}
			}
			parts = append(parts, p.next().Text)
		}
		if len(parts) == 1 {
			return &identExpr{Name: name}, nil
		}
		return &traversalExpr{Parts: parts}, nil
	case tokenLBracket:
		p.next()
		var elems []expr
		if p.peek().Kind != tokenRBracket {
			for {
				elem, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				elems = append(elems, elem)
				if p.peek().Kind != tokenComma {
					break
				}
				p.next()
			}
		}
		if p.peek().Kind != tokenRBracket {
			return nil, parseError{Path: p.path, Token: p.peek()}
		}
		p.next()
		return &listExpr{Elems: elems}, nil
	default:
		return nil, parseError{Path: p.path, Token: tok}
	}
}

func (p *parser) peek() token {
	return p.tokens[p.pos]
}

func (p *parser) next() token {
	tok := p.tokens[p.pos]
	if tok.Kind != tokenEOF {
		p.pos++
	}
	return tok
}

func FormatHCL(src []byte) []byte {
	file, err := parseFile("", src)
	if err == nil {
		return formatAST(file)
	}
	return formatFallback(tokenize(src))
}

func formatAST(file *fileNode) []byte {
	var b strings.Builder
	for i, item := range file.Items {
		if i > 0 {
			b.WriteString("\n\n")
		}
		writeNode(&b, item, 0)
	}
	if b.Len() > 0 {
		b.WriteByte('\n')
	}
	return []byte(b.String())
}

func writeNode(b *strings.Builder, item node, indent int) {
	prefix := strings.Repeat(" ", indent)
	switch n := item.(type) {
	case *attrNode:
		b.WriteString(prefix)
		b.WriteString(n.Name)
		b.WriteString(" = ")
		writeExpr(b, n.Expr)
	case *blockNode:
		b.WriteString(prefix)
		b.WriteString(n.Type)
		for _, label := range n.Labels {
			b.WriteByte(' ')
			b.WriteString(label.Raw)
		}
		if len(n.Items) == 0 {
			b.WriteString(" {}")
			return
		}
		b.WriteString(" {\n")
		for i, child := range n.Items {
			if i > 0 {
				b.WriteByte('\n')
			}
			writeNode(b, child, indent+2)
		}
		b.WriteByte('\n')
		b.WriteString(prefix)
		b.WriteByte('}')
	}
}

func writeExpr(b *strings.Builder, value expr) {
	switch v := value.(type) {
	case *stringExpr:
		b.WriteString(v.Raw)
	case *numberExpr:
		b.WriteString(v.Raw)
	case *boolExpr:
		if v.Value {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case *identExpr:
		b.WriteString(v.Name)
	case *traversalExpr:
		b.WriteString(strings.Join(v.Parts, "."))
	case *callExpr:
		b.WriteString(v.Name)
		b.WriteByte('(')
		for i, arg := range v.Args {
			if i > 0 {
				b.WriteString(", ")
			}
			writeExpr(b, arg)
		}
		b.WriteByte(')')
	case *listExpr:
		b.WriteByte('[')
		for i, elem := range v.Elems {
			if i > 0 {
				b.WriteString(", ")
			}
			writeExpr(b, elem)
		}
		b.WriteByte(']')
	}
}

func formatFallback(tokens []token) []byte {
	var b strings.Builder
	indent := 0
	lineStart := true
	var prev token
	hasPrev := false
	for i := 0; i < len(tokens); i++ {
		tok := tokens[i]
		if tok.Kind == tokenEOF {
			break
		}
		if hasPrev && tok.Line > prev.Line {
			if !lineStart {
				b.WriteByte('\n')
			}
			lineStart = true
		}
		switch tok.Kind {
		case tokenIdent, tokenString, tokenNumber:
			if lineStart {
				b.WriteString(strings.Repeat(" ", indent))
			} else if needsSpace(prev, tok) {
				b.WriteByte(' ')
			}
			b.WriteString(tok.Text)
			lineStart = false
		case tokenDot:
			b.WriteByte('.')
			lineStart = false
		case tokenEqual:
			b.WriteString(" = ")
			lineStart = false
		case tokenComma:
			b.WriteString(", ")
			lineStart = false
		case tokenLBracket:
			if lineStart {
				b.WriteString(strings.Repeat(" ", indent))
			}
			b.WriteByte('[')
			lineStart = false
		case tokenRBracket:
			b.WriteByte(']')
			lineStart = false
		case tokenLParen:
			b.WriteByte('(')
			lineStart = false
		case tokenRParen:
			b.WriteByte(')')
			lineStart = false
		case tokenLBrace:
			if lineStart {
				b.WriteString(strings.Repeat(" ", indent))
			} else if prev.Kind != tokenLBrace && prev.Kind != tokenDot && prev.Kind != tokenLParen && prev.Kind != tokenLBracket {
				b.WriteByte(' ')
			}
			if i+1 < len(tokens) && tokens[i+1].Kind == tokenRBrace {
				b.WriteString("{}")
				i++
				lineStart = false
			} else {
				b.WriteByte('{')
				indent += 2
				b.WriteByte('\n')
				lineStart = true
			}
		case tokenRBrace:
			if !lineStart {
				b.WriteByte('\n')
			}
			if indent >= 2 {
				indent -= 2
			}
			b.WriteString(strings.Repeat(" ", indent))
			b.WriteByte('}')
			lineStart = false
		}
		prev = tok
		hasPrev = true
	}
	if !lineStart && b.Len() > 0 {
		b.WriteByte('\n')
	}
	return []byte(b.String())
}

func needsSpace(prev, cur token) bool {
	switch prev.Kind {
	case tokenIdent, tokenString, tokenNumber, tokenRBracket, tokenRParen:
		switch cur.Kind {
		case tokenIdent, tokenString, tokenNumber:
			return true
		}
	}
	return false
}

type valueKind int

const (
	valueString valueKind = iota
	valueList
)

type evalValue struct {
	Kind valueKind
	Str  string
	List []evalValue
}

func (v evalValue) asString() string {
	if v.Kind == valueString {
		return v.Str
	}
	return ""
}

type EvalConfig struct {
	path        string
	file        *fileNode
	envs        map[string]*blockNode
	vars        map[string]expr
	overrides   map[string]string
	locals      map[string]expr
	selectedEnv string
	envValues   map[string]evalValue
	localCache  map[string]evalValue
}

func LoadEvalConfig(path string) (*EvalConfig, error) {
	if _, err := os.Stat(path); err != nil {
		return nil, fmt.Errorf("config file %q was not found: %w", path, err)
	}
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	file, err := parseFile(path, src)
	if err != nil {
		return nil, err
	}
	cfg := &EvalConfig{
		path:       path,
		file:       file,
		envs:       map[string]*blockNode{},
		vars:       map[string]expr{},
		overrides:  map[string]string{},
		locals:     map[string]expr{},
		localCache: map[string]evalValue{},
	}
	for _, item := range file.Items {
		block, ok := item.(*blockNode)
		if !ok {
			continue
		}
		switch block.Type {
		case "env":
			if len(block.Labels) > 0 {
				cfg.envs[block.Labels[0].Value] = block
			}
		case "variable":
			if len(block.Labels) == 0 {
				continue
			}
			for _, child := range block.Items {
				attr, ok := child.(*attrNode)
				if ok && attr.Name == "default" {
					cfg.vars[block.Labels[0].Value] = attr.Expr
				}
			}
		case "locals":
			for _, child := range block.Items {
				attr, ok := child.(*attrNode)
				if ok {
					cfg.locals[attr.Name] = attr.Expr
				}
			}
		}
	}
	return cfg, nil
}

func (c *EvalConfig) ParseOnly() error { return nil }

func (c *EvalConfig) UseEnv(name string) error {
	if _, ok := c.envs[name]; !ok {
		return fmt.Errorf("env %q not defined in config file", name)
	}
	c.selectedEnv = name
	return nil
}

func (c *EvalConfig) SetVar(name, value string) {
	c.overrides[name] = value
}

func (c *EvalConfig) Evaluate() error {
	if c.selectedEnv == "" {
		return nil
	}
	block := c.envs[c.selectedEnv]
	values := map[string]evalValue{}
	for _, child := range block.Items {
		attr, ok := child.(*attrNode)
		if !ok {
			continue
		}
		value, err := c.evalExpr(attr.Expr, map[string]bool{})
		if err != nil {
			return err
		}
		values[attr.Name] = value
	}
	c.envValues = values
	return nil
}

func (c *EvalConfig) EnvValue(name string) string {
	if c.envValues == nil {
		return ""
	}
	return c.envValues[name].asString()
}

func (c *EvalConfig) evalExpr(expression expr, localsSeen map[string]bool) (evalValue, error) {
	switch v := expression.(type) {
	case *stringExpr:
		unquoted, err := strconv.Unquote(v.Raw)
		if err != nil {
			return evalValue{}, err
		}
		out, err := c.interpolate(unquoted, localsSeen)
		if err != nil {
			return evalValue{}, err
		}
		return evalValue{Kind: valueString, Str: out}, nil
	case *numberExpr:
		return evalValue{Kind: valueString, Str: v.Raw}, nil
	case *boolExpr:
		if v.Value {
			return evalValue{Kind: valueString, Str: "true"}, nil
		}
		return evalValue{Kind: valueString, Str: "false"}, nil
	case *identExpr:
		return evalValue{Kind: valueString, Str: v.Name}, nil
	case *traversalExpr:
		return c.evalTraversal(v, localsSeen)
	case *callExpr:
		if v.Name == "getenv" && len(v.Args) == 1 {
			arg, err := c.evalExpr(v.Args[0], localsSeen)
			if err != nil {
				return evalValue{}, err
			}
			return evalValue{Kind: valueString, Str: os.Getenv(arg.asString())}, nil
		}
		return evalValue{Kind: valueString, Str: v.Name}, nil
	case *listExpr:
		values := make([]evalValue, 0, len(v.Elems))
		for _, elem := range v.Elems {
			item, err := c.evalExpr(elem, localsSeen)
			if err != nil {
				return evalValue{}, err
			}
			values = append(values, item)
		}
		return evalValue{Kind: valueList, List: values}, nil
	default:
		return evalValue{}, errors.New("unsupported expression")
	}
}

func (c *EvalConfig) evalTraversal(v *traversalExpr, localsSeen map[string]bool) (evalValue, error) {
	if len(v.Parts) >= 2 {
		switch v.Parts[0] {
		case "var":
			name := v.Parts[1]
			if override, ok := c.overrides[name]; ok {
				return evalValue{Kind: valueString, Str: override}, nil
			}
			if expr, ok := c.vars[name]; ok {
				return c.evalExpr(expr, localsSeen)
			}
		case "local":
			name := v.Parts[1]
			if value, ok := c.localCache[name]; ok {
				return value, nil
			}
			if localsSeen[name] {
				return evalValue{}, fmt.Errorf("cycle in locals")
			}
			expr, ok := c.locals[name]
			if !ok {
				return evalValue{}, nil
			}
			clone := make(map[string]bool, len(localsSeen)+1)
			for key, seen := range localsSeen {
				clone[key] = seen
			}
			clone[name] = true
			value, err := c.evalExpr(expr, clone)
			if err != nil {
				return evalValue{}, err
			}
			c.localCache[name] = value
			return value, nil
		case "atlas":
			if v.Parts[1] == "env" {
				return evalValue{Kind: valueString, Str: c.selectedEnv}, nil
			}
		}
	}
	return evalValue{Kind: valueString, Str: strings.Join(v.Parts, ".")}, nil
}

func (c *EvalConfig) interpolate(text string, localsSeen map[string]bool) (string, error) {
	if !strings.Contains(text, "${") {
		return text, nil
	}
	var b strings.Builder
	for {
		start := strings.Index(text, "${")
		if start < 0 {
			b.WriteString(text)
			break
		}
		b.WriteString(text[:start])
		text = text[start+2:]
		end := strings.IndexByte(text, '}')
		if end < 0 {
			b.WriteString("${")
			b.WriteString(text)
			break
		}
		exprText := text[:end]
		text = text[end+1:]
		exprNode, err := parseInlineExpr(exprText)
		if err != nil {
			return "", err
		}
		value, err := c.evalExpr(exprNode, localsSeen)
		if err != nil {
			return "", err
		}
		b.WriteString(value.asString())
	}
	return b.String(), nil
}

func parseInlineExpr(text string) (expr, error) {
	p := parser{tokens: tokenize([]byte(text))}
	value, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	return value, nil
}

func filePathFromURL(raw string) (string, error) {
	switch {
	case strings.HasPrefix(raw, "file:///"):
		return raw[len("file://"):], nil
	case strings.HasPrefix(raw, "file://"):
		return raw[len("file://"):], nil
	case raw == "":
		return "", nil
	default:
		return raw, nil
	}
}

func sortedKeys[K ~string, V any](m map[K]V) []K {
	keys := make([]K, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sort.Slice(keys, func(i, j int) bool { return keys[i] < keys[j] })
	return keys
}

func normalizeLineEndings(src []byte) []byte {
	return bytes.ReplaceAll(src, []byte("\r\n"), []byte("\n"))
}

