type sqliteDB struct {
	ptr *C.sqlite3
}

func openSQLite(raw string) (*sqliteDB, error) {
	dsn := sqliteDSN(raw)
	cdsn := C.CString(dsn)
	defer C.free(unsafe.Pointer(cdsn))
	var db *C.sqlite3
	flags := C.int(C.SQLITE_OPEN_READWRITE | C.SQLITE_OPEN_CREATE | C.SQLITE_OPEN_URI)
	if rc := C.sqlite3_open_v2(cdsn, &db, flags, nil); rc != 0 {
		if db != nil {
			defer C.sqlite3_close(db)
			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
		}
		return nil, fmt.Errorf("unable to open sqlite database")
	}
	return &sqliteDB{ptr: db}, nil
}

func (db *sqliteDB) Close() {
	if db.ptr != nil {
		C.sqlite3_close(db.ptr)
		db.ptr = nil
	}
}

func (db *sqliteDB) QueryRows(query string) ([][]string, error) {
	cquery := C.CString(query)
	defer C.free(unsafe.Pointer(cquery))
	var stmt *C.sqlite3_stmt
	if rc := C.sqlite3_prepare_v2(db.ptr, cquery, -1, &stmt, nil); rc != 0 {
		return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db.ptr)))
	}
	defer C.sqlite3_finalize(stmt)
	var rows [][]string
	for {
		rc := C.sqlite3_step(stmt)
		if rc == C.SQLITE_DONE {
			return rows, nil
		}
		if rc != C.SQLITE_ROW {
			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db.ptr)))
		}
		n := int(C.sqlite3_column_count(stmt))
		row := make([]string, n)
		for i := 0; i < n; i++ {
			text := C.sqlite3_column_text(stmt, C.int(i))
			if text != nil {
				row[i] = C.GoString((*C.char)(unsafe.Pointer(text)))
			}
		}
		rows = append(rows, row)
	}
}

func sqliteDSN(raw string) string {
	rest := strings.TrimPrefix(raw, "sqlite://")
	if rest == "" {
		return ":memory:"
	}
	if strings.HasPrefix(rest, "file:") {
		return rest
	}
	if strings.Contains(rest, "?") {
		return "file:" + rest
	}
	return rest
}

