func writeMigrationSum(dir string) error {
	info, err := os.Stat(dir)
	if err != nil {
		return fmt.Errorf("sql/migrate: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("sql/migrate: stat %s: not a directory", dir)
	}
	files, err := migrationFiles(dir)
	if err != nil {
		return err
	}
	sum := migrationSum(files)
	return os.WriteFile(filepath.Join(dir, "atlas.sum"), []byte(sum), 0o644)
}

func createMigration(dir string, now time.Time, name string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	stem := now.Format("20060102150405")
	if name != "" {
		stem += "_" + name
	}
	path := filepath.Join(dir, stem+".sql")
	if err := os.WriteFile(path, []byte{}, 0o644); err != nil {
		return err
	}
	return writeMigrationSum(dir)
}

func validateMigrationDir(dir string) error {
	info, err := os.Stat(dir)
	if err != nil {
		return fmt.Errorf("sql/migrate: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("sql/migrate: stat %s: not a directory", dir)
	}
	files, err := migrationFiles(dir)
	if err != nil {
		return err
	}
	sumPath := filepath.Join(dir, "atlas.sum")
	sumData, err := os.ReadFile(sumPath)
	if err != nil {
		if os.IsNotExist(err) {
			if len(files) == 0 {
				return nil
			}
			return fmt.Errorf("checksum file not found")
		}
		return err
	}
	expected := strings.TrimSpace(string(sumData))
	actual := strings.TrimSpace(migrationSum(files))
	if expected != actual {
		return fmt.Errorf("checksum mismatch")
	}
	return nil
}

type migrationFile struct {
	Name string
	Body []byte
}

func migrationFiles(dir string) ([]migrationFile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: %w", err)
	}
	var names []string
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		if filepath.Ext(entry.Name()) != ".sql" {
			continue
		}
		names = append(names, entry.Name())
	}
	sort.Strings(names)
	files := make([]migrationFile, 0, len(names))
	for _, name := range names {
		body, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			return nil, err
		}
		files = append(files, migrationFile{Name: name, Body: body})
	}
	return files, nil
}

func migrationSum(files []migrationFile) string {
	var lines []string
	var concat strings.Builder
	for _, file := range files {
		hash := base64sha256([]byte(file.Name), file.Body)
		lines = append(lines, fmt.Sprintf("%s h1:%s", file.Name, hash))
