			b.WriteString("CREATE TABLE `")
			b.WriteString(table.Name)
			b.WriteString("` (")
			items := sqlItems(table)
			for i, item := range items {
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString(item)
			}
			b.WriteString(");\n")
			continue
		}
		b.WriteString("CREATE TABLE `")
		b.WriteString(table.Name)
		b.WriteString("` (\n")
		items := sqlItems(table)
		for i, item := range items {
			b.WriteString(indent)
			b.WriteString(item)
			if i < len(items)-1 {
				b.WriteByte(',')
			}
			b.WriteByte('\n')
		}
		b.WriteString(");\n")
	}
	return b.String()
}

func sqlItems(table Table) []string {
	var items []string
	for _, column := range table.Columns {
		nullWord := "NOT NULL"
		if column.Null {
			nullWord = "NULL"
		}
		items = append(items, fmt.Sprintf("`%s` %s %s", column.Name, strings.ToLower(column.Type), nullWord))
	}
	if table.PrimaryKey != nil {
		var parts []string
		for _, part := range table.PrimaryKey.Parts {
			parts = append(parts, fmt.Sprintf("`%s`", part.Column))
		}
		items = append(items, fmt.Sprintf("PRIMARY KEY (%s)", strings.Join(parts, ", ")))
	}
	for _, fk := range table.ForeignKeys {
		var cols []string
		for _, column := range fk.Columns {
			cols = append(cols, fmt.Sprintf("`%s`", column))
		}
		var refs []string
		for _, column := range fk.References.Columns {
			refs = append(refs, fmt.Sprintf("`%s`", column))
		}
		items = append(items, fmt.Sprintf("CONSTRAINT `%s` FOREIGN KEY (%s) REFERENCES `%s` (%s) ON UPDATE %s ON DELETE %s", fk.Name, strings.Join(cols, ", "), fk.References.Table, strings.Join(refs, ", "), fk.OnUpdate, fk.OnDelete))
	}
	return items
}

func renderMermaid(state *SchemaState) string {
	var b strings.Builder
	b.WriteString("erDiagram\n")
	if len(state.Schemas) == 0 {
		return b.String()
	}
	for _, table := range state.Schemas[0].Tables {
		b.WriteString("    ")
		b.WriteString(table.Name)
		b.WriteString(" {\n")
		for _, column := range table.Columns {
			b.WriteString("      ")
			b.WriteString(strings.ToLower(column.Type))
			b.WriteByte(' ')
			b.WriteString(column.Name)
			if isPrimaryKeyColumn(table, column.Name) {
				b.WriteString(" PK")
			} else if isForeignKeyColumn(table, column.Name) {
				b.WriteString(" FK")
			}
			b.WriteByte('\n')
		}
		b.WriteString("    }\n")
	}
	for _, table := range state.Schemas[0].Tables {
		for _, fk := range table.ForeignKeys {
			b.WriteString("    ")
			b.WriteString(table.Name)
			b.WriteString(" }o--o| ")
			b.WriteString(fk.References.Table)
			b.WriteString(" : ")
			b.WriteString(fk.Name)
			b.WriteByte('\n')
		}
	}
	return b.String()
}

func isPrimaryKeyColumn(table Table, name string) bool {
	if table.PrimaryKey == nil {
		return false
	}
	for _, part := range table.PrimaryKey.Parts {
		if part.Column == name {
			return true
		}
	}
	return false
}

func isForeignKeyColumn(table Table, name string) bool {
	for _, fk := range table.ForeignKeys {
		for _, column := range fk.Columns {
			if column == name {
				return true
			}
		}
	}
	return false
}

